public class Bits {

    public static int[] countBits(int n) {
        int[] dp = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            dp[i] = dp[i >> 1] + (i & 1); // drop the lowest bit, reuse that answer
        }
        return dp;
    }
}

