public class Reverse {

    public static int reverseBits(int n) {
        int result = 0;
        for (int i = 0; i < 32; i++) {
            result = (result << 1) | (n & 1); // push the lowest bit of n into result
            n >>>= 1; // unsigned shift: no sign bit copied in
        }
        return result;
    }
}

import java.util.*;

// Grader test class (do not edit): one command per input line; after each command it prints the result and the
// state read from the REAL links of your structure (Kiem follows the fields node by node).
public class KiemTra {
    static String[] p;

    static int n(int i) {
        return Integer.parseInt(p[i]);
    }

    static int[] arr(String s) {
        if (s.equals("-")) {
            return new int[0];
        }
        String[] t = s.split(",");
        int[] a = new int[t.length];
        for (int i = 0; i < t.length; i++) {
            a[i] = Integer.parseInt(t[i].trim());
        }
        return a;
    }

    static String str(int[] a) {
        return Arrays.toString(a);
    }

    static String ketQua(String label, int n, String sai) {
        return sai == null ? label + ": all " + n + " agree with the brute force" : label + ": MISMATCH " + sai;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) {
                continue;
            }
            p = line.split("\\s+");
            String r = "ok";
            try {
                if (p[0].equals("RUN")) {
                    r = String.valueOf(Reverse.reverseBits(n(1)));
                } else {
                    Random rnd = new Random(141);
                    String sai = null;
                    int[] ext = {0, 1, -1, Integer.MIN_VALUE, Integer.MAX_VALUE};
                    for (int t = 0; t < 100000 && sai == null; t++) {
                        int x = t < ext.length ? ext[t] : rnd.nextInt();
                        int got = Reverse.reverseBits(x), want = Integer.reverse(x);
                        if (got != want) {
                            sai = x + " -> " + got + ", expected " + want;
                        }
                    }
                    r = ketQua("100,000 ints (0, -1, MIN, MAX too)", 100000, sai);
                }
            } catch (RuntimeException e) {
                r = "THROWS " + Kiem.ten(e);
            }
            System.out.println(line + " -> " + r);
        }
    }
}

